const clamp01 = (value) => Math.max(0, Math.min(1, Number.isFinite(value) ? value : 0));
export function bossTelegraphReengagementLockPresentation(input, reducedFlash = false) { const reacquire = clamp01(input.reacquire), crowd = clamp01(input.crowd), lock = input.active ? clamp01(crowd * .62 + (1 - reacquire) * .38) : 0; return { lock, edgeAlphaScale: input.active ? Math.max(input.critical ? .96 : .94, .99 * (reducedFlash ? .98 : 1)) : 1, staleDecorationScale: Math.max(.5, 1 - lock * .44) * (reducedFlash ? .94 : 1), presentationOnly: true }; }
export function bossProjectileReengagementLockPresentation(input, reducedMotion = false, reducedFlash = false) { const reacquire = clamp01(input.reacquire), lane = clamp01(input.laneProximity), crowd = clamp01(input.crowd), lock = input.active ? clamp01(lane * .38 + crowd * .34 + (1 - reacquire) * .28) : 0; return { lock, bodyScale: 1, trailScale: Math.max(input.critical ? .8 : .58, 1 - lock * (input.critical ? .16 : .36)) * (reducedMotion ? .96 : 1), secondaryScale: Math.max(.54, 1 - lock * .4) * (reducedFlash ? .94 : 1), presentationOnly: true }; }
export function bossImpactReengagementLockPresentation(input, reducedFlash = false) { const boss = clamp01(input.bossProximity), reacquire = clamp01(input.reacquire), crowd = clamp01(input.crowd), lock = clamp01(boss * .54 + crowd * .28 + (1 - reacquire) * .18), flash = reducedFlash ? .9 : 1, fillAlphaScale = Math.max(input.critical ? .58 : .24, 1 - lock * (input.critical ? .36 : .62)) * flash, edgeAlphaScale = Math.max(fillAlphaScale, input.critical ? .9 : .72, .72 + (1 - lock) * .2); return { lock, fillAlphaScale, edgeAlphaScale, presentationOnly: true }; }
export function safeLaneCriticalReengagementLockPresentation(input, reducedFlash = false) { const confidence = clamp01(input.confidence), pressure = clamp01(input.bossPressure), reacquire = clamp01(input.reacquire), lock = clamp01(pressure * .7 + (1 - reacquire) * .3); return { lock, pathAlphaFloor: input.visible ? Math.max(input.critical ? .95 : .93, .92 + confidence * .06) : 0, safeLaneScale: input.visible ? 1 + lock * (.07 + .03 * confidence) * (reducedFlash ? .8 : 1) : 1, secondaryScale: Math.max(.56, 1 - lock * .38), presentationOnly: true }; }
export function specialistBossReengagementLockPresentation(input, reducedMotion = false) { const boss = clamp01(input.bossProximity), reacquire = clamp01(input.reacquire), action = input.owner === 'special' ? 1 : input.owner === 'attack' ? .9 : input.owner === 'hit' ? .72 : input.owner === 'recovery' ? .5 : .2, lock = clamp01(boss * (.56 + (1 - reacquire) * .24)); return { lock, bodyScale: 1, directionScale: Math.max(input.critical ? .9 : .8, .8 + action * .14 - lock * .05), secondaryScale: Math.max(.5, 1 - lock * .44) * (reducedMotion ? .95 : 1), presentationOnly: true }; }
export function criticalReengagementBudgetPresentation(input, reducedMotion = false, reducedFlash = false) { const critical = clamp01(Math.max(0, input.criticalCount) / 3), load = clamp01((input.projectileCount + input.impactCount + input.hazardCount * 1.4 + input.silhouetteCount) / 30), lock = input.bossActive ? clamp01(load * .78 + critical * .3) : 0; return { lock, canonicalScale: 1, telegraphEdgeScale: 1, safeLaneScale: input.safeLaneVisible ? 1 + lock * .06 * (reducedFlash ? .8 : 1) : 1, secondaryScale: Math.max(.48, 1 - lock * .46) * (reducedMotion ? .95 : 1) * (reducedFlash ? .94 : 1), presentationOnly: true }; }
